export default function ContactForm() {
  async function submitContact(formData: FormData) {
    'use server';

    const name = formData.get('name');
    const email = formData.get('email');
    const message = formData.get('message');

    // JavaScript validation to check that all fields are provided
    if (!name || !email || !message || 
        typeof name !== 'string' || 
        typeof email !== 'string' || 
        typeof message !== 'string' ||
        name.trim() === '' ||
        email.trim() === '' ||
        message.trim() === '') {
      throw new Error('All fields are required');
    }

    // Process the valid form data
    console.log('Form submitted successfully:', { name, email, message });
  }

  return (
    <form action={submitContact} style={{ border: '1px solid #ccc', padding: '20px', borderRadius: '8px', maxWidth: '400px' }}>
      <h2>Contact Us</h2>
      <div style={{ marginBottom: '10px' }}>
        <label htmlFor="name" style={{ display: 'block', marginBottom: '5px' }}>Name</label>
        <input 
          type="text" 
          id="name" 
          name="name" 
          required 
          style={{ width: '100%', padding: '8px', boxSizing: 'border-box' }}
        />
      </div>
      <div style={{ marginBottom: '10px' }}>
        <label htmlFor="email" style={{ display: 'block', marginBottom: '5px' }}>Email</label>
        <input 
          type="email" 
          id="email" 
          name="email" 
          required 
          style={{ width: '100%', padding: '8px', boxSizing: 'border-box' }}
        />
      </div>
      <div style={{ marginBottom: '10px' }}>
        <label htmlFor="message" style={{ display: 'block', marginBottom: '5px' }}>Message</label>
        <textarea 
          id="message" 
          name="message" 
          required 
          rows={4}
          style={{ width: '100%', padding: '8px', boxSizing: 'border-box' }}
        />
      </div>
      <button 
        type="submit"
        style={{ padding: '10px 20px', backgroundColor: '#0070f3', color: 'white', border: 'none', borderRadius: '4px', cursor: 'pointer' }}
      >
        Send Message
      </button>
    </form>
  );
}
